@page "/catalog"
@using sv_f2c64d700110492eac579a71e5584f08.Components.Catalog
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<h3 class="mb-3">Product Catalog</h3>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @_error
        <button class="btn btn-sm btn-outline-danger ms-2" @onclick="RetryAsync">Retry</button>
    </div>
}
else
{
    <div class="row">
        @* Sidebar filters — ~25% width *@
        <div class="col-md-3 mb-3">
            <CatalogFilters Categories="@_categories" OnFiltersApplied="HandleFiltersApplied" />
        </div>

        @* Main content — ~75% width *@
        <div class="col-md-9">
            @if (_loading)
            {
                <div class="d-flex justify-content-center align-items-center py-5">
                    <div class="spinner-border text-primary" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                </div>
            }
            else if (_result is not null && _result.Items.Count > 0)
            {
                <CatalogToolbar SortBy="@_sortBy"
                                TotalCount="@_result.TotalCount"
                                Page="@_currentPage"
                                PageSize="@PageSize"
                                OnSortChanged="HandleSortChanged" />

                <ProductGrid Products="@_result.Items"
                             OnProductSelected="OnProductSelected"
                             OnAddToCart="OnAddToCart" />

                <CatalogPagination CurrentPage="@_currentPage"
                                   TotalPages="@TotalPages"
                                   OnPageChanged="HandlePageChanged" />
            }
            else
            {
                <div class="text-center py-5 text-muted">
                    <h5>No products found</h5>
                    <p>Try adjusting your filters.</p>
                </div>
            }
        </div>
    </div>
}

@code {
    private const int PageSize = 12;

    /// <summary>Raised when a product card is clicked for navigation to a detail page.</summary>
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    /// <summary>Raised when the Add to Cart button is clicked.</summary>
    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private List<string> _categories = [];
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private PagedResult<Product>? _result;
    private bool _loading = true;
    private string? _error;

    private int TotalPages => _result is null || _result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)_result.TotalCount / PageSize);

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        try
        {
            _loading = true;
            _error = null;

            // Load categories and first page of products in parallel
            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);

            await Task.WhenAll(categoriesTask, productsTask);

            _categories = await categoriesTask;
            _result = await productsTask;
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task SearchAsync()
    {
        try
        {
            _loading = true;
            _error = null;
            _result = await ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleFiltersApplied(ProductFilter filter)
    {
        _filter = filter;
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await SearchAsync();
    }

    private async Task RetryAsync()
    {
        await LoadDataAsync();
    }
}

